const box = document.querySelector('[class*="goods-overview-new_cardBox"]') || document.body;
const items = Array.from(box.querySelectorAll('[class*="card_cardItem"]'));
const rows = [];
for (const it of items) {
  const parts = (it.innerText || '').split('\n').map(function (s) { return s.trim(); }).filter(Boolean);
  if (parts.length < 2) continue;
  const label = parts[0];
  const today = parts[1] === '--' ? '' : parts[1];
  let yesterday = '';
  for (let i = 2; i < parts.length - 1; i += 1) {
    if (parts[i] === '昨日') {
      yesterday = parts[i + 1] === '--' ? '' : parts[i + 1];
      break;
    }
  }
  rows.push({ label: label, today: today, yesterday: yesterday });
}
const m = (document.body.innerText || '').match(/统计时间：(\d{4}-\d{2}-\d{2})/);
return JSON.stringify({ asOf: m ? m[1] : '', items: rows });
